// Renders the token sections of /design-system from assets/js/tokens.js (generated by `npm run tokens`).
(() => {
  const data = window.CBJ_TOKENS;
  if (!data) return;
  const theme = data.themes.find((t) => t.default) || data.themes[0];
  const all = theme.tokens;
  const $ = (sel) => document.querySelector(sel);
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

  const by = (fn) => all.filter(fn);
  const set = (sel, html) => { const el = $(sel); if (el) el.innerHTML = html; };

  set('[data-ds="theme-name"]', esc(theme.name));
  set('[data-ds="generated"]', esc(new Date(data.generated).toLocaleString()));
  set('[data-ds="count"]', String(all.length));

  // Core palette swatches
  const swatch = (t) => `<button type="button" class="ds-swatch" data-copy="var(${t.cssVar})" title="Copy var(${t.cssVar})">
      <span class="ds-swatch__chip"><span style="background:${t.value}"></span></span>
      <span class="ds-swatch__meta">
        <span class="meta">${esc(t.path.replace(/^color\./, ''))}</span>
        <span class="mono text-tertiary">${esc(t.value)}</span>
        ${t.description ? `<span class="mono text-tertiary">${esc(t.description)}</span>` : ''}
      </span>
    </button>`;
  set('[data-ds="core-colors"]', by((t) => t.tier === 'core' && t.type === 'color').map(swatch).join(''));

  // Tables
  const row = (t) => `<tr>
      <td>${t.type === 'color' ? `<span class="ds-mini" style="background:${t.value}"></span>` : ''}<code>${esc(t.cssVar)}</code></td>
      <td class="ds-alias">${t.alias ? esc('{' + t.alias + '}') : '—'}</td>
      <td><code>${esc(t.value)}</code></td>
      <td class="text-secondary">${esc(t.description || '')}</td>
    </tr>`;
  const table = (rows) => `<div class="ds-table-wrap"><table class="ds-table">
      <thead><tr><th>Variable</th><th>Alias</th><th>Resolved</th><th>Note</th></tr></thead>
      <tbody>${rows.map(row).join('')}</tbody></table></div>`;

  set('[data-ds="semantic-colors"]', table(by((t) => t.tier === 'semantic' && t.type === 'color')));
  set('[data-ds="semantic-other"]', table(by((t) => t.tier === 'semantic' && t.type !== 'color')));
  set('[data-ds="component-tokens"]', table(by((t) => t.tier === 'component')));
  set('[data-ds="core-type"]', table(by((t) => t.tier === 'core' && t.path.startsWith('font.'))));
  set('[data-ds="core-motion"]', table(by((t) => t.path.startsWith('motion.') || t.path.startsWith('blur.') || t.path.startsWith('size.'))));

  // Spacing scale
  const px = (v) => parseFloat(v) || 0;
  const space = by((t) => t.path.startsWith('space.'));
  const max = Math.max(...space.map((t) => px(t.value)));
  set('[data-ds="space"]', space.map((t) => `<div class="ds-scale__row">
      <code class="mono">${esc(t.cssVar)}</code><span class="mono text-tertiary">${esc(t.value)}</span>
      <span class="ds-scale__bar" style="width:${(px(t.value) / max) * 100}%"></span></div>`).join(''));

  // Radius
  set('[data-ds="radius"]', by((t) => t.path.startsWith('radius.')).map((t) =>
    `<div style="border-radius:${t.value}"><span class="mono">${esc(t.path.replace('radius.', ''))}</span></div>`).join(''));

  // Click to copy
  const toast = $('.ds-toast');
  document.addEventListener('click', async (e) => {
    const el = e.target.closest('[data-copy]');
    if (!el) return;
    try {
      await navigator.clipboard.writeText(el.dataset.copy);
      if (toast) {
        toast.textContent = `Copied ${el.dataset.copy}`;
        toast.dataset.show = 'true';
        clearTimeout(toast._t);
        toast._t = setTimeout(() => { toast.dataset.show = 'false'; }, 1400);
      }
    } catch { /* clipboard unavailable (e.g. file://) */ }
  });
})();
